def sum_first_n_fibonacci(n):
    if n <= 0:
        return 0
    a, b = 0, 1
    total = 0
    for _ in range(n):
        total += a
        a, b = b, a + b
    return total

def custom_fibonacci(a, b, n):
    if n == 0:
        return a
    if n == 1:
        return b
    for _ in range(n - 1):
        a, b = b, a + b
    return b

def nth_lucas_number(n):
    if n == 0:
        return 2
    if n == 1:
        return 1
    a, b = 2, 1
    for _ in range(n - 1):
        a, b = b, a + b
    return b

