def nth_catalan_number(n):
    return comb(2 * n, n) // (n + 1)

def count_divisors_of_factorial(n):
    if n <= 1:
        return 1
    sieve = [True] * (n + 1)
    sieve[0] = False
    sieve[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            for j in range(i * i, n + 1, i):
                sieve[j] = False
    primes = [i for i, is_p in enumerate(sieve) if is_p]
    result = 1
    for p in primes:
        exponent = 0
        power = p
        while power <= n:
            exponent += n // power
            power *= p
        result *= (exponent + 1)
    return result

def smallest_number_with_digit_sum(s, d):
    if d <= 0 or s < 0:
        return -1
    if s > 9 * d:
        return -1
    digits = []
    remaining = s
    for i in range(d):
        min_digit = 1 if i == 0 else 0
        rest = d - i - 1
        low = max(min_digit, remaining - rest * 9)
        if low > 9 or low > remaining:
            return -1
        digits.append(low)
        remaining -= low
    if remaining != 0:
        return -1
    return int(''.join(str(x) for x in digits))

def count_matching_digit_positions(a, b):
    sa, sb = str(a), str(b)
    length = max(len(sa), len(sb))
    sa = sa.zfill(length)
    sb = sb.zfill(length)
    return sum(1 for x, y in zip(sa, sb) if x == y)

def sum_even_fibonacci_below(n):
    a, b = 0, 1
    total = 0
    while a < n:
        if a % 2 == 0:
            total += a
        a, b = b, a + b
    return total

def count_polite_representations(n):
    count = 0
    k = 2
    while k * (k + 1) // 2 <= n:
        numerator = n - k * (k - 1) // 2
        if numerator % k == 0:
            a = numerator // k
            if a >= 1:
                count += 1
        k += 1
    return count

def goldbach_pair(n):
    def is_prime(x):
        if x < 2:
            return False
        if x < 4:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True

    p = 2
    while p <= n // 2:
        q = n - p
        if is_prime(p) and is_prime(q):
            return (p, q)
        p += 1
    return None

def count_goldbach_pairs(n):
