def count_palindromes_in_range(a, b):
    count = 0
    for x in range(a, b + 1):
        s = str(x)
        if s == s[::-1]:
            count += 1
    return count

def count_armstrong_in_range(a, b):
    count = 0
    for x in range(a, b + 1):
        s = str(x)
        k = len(s)
        if x == sum(int(d) ** k for d in s):
            count += 1
    return count

def count_happy_numbers_in_range(a, b):
    def is_happy(x):
        seen = set()
        while x != 1 and x not in seen:
            seen.add(x)
            x = sum(int(d) ** 2 for d in str(x))
        return x == 1

    count = 0
    for x in range(a, b + 1):
        if is_happy(x):
            count += 1
    return count

def nth_ugly_number(n):
    ugly = [1] * n
    i2 = i3 = i5 = 0
    for i in range(1, n):
        next2, next3, next5 = ugly[i2] * 2, ugly[i3] * 3, ugly[i5] * 5
        next_ugly = min(next2, next3, next5)
        ugly[i] = next_ugly
        if next_ugly == next2:
            i2 += 1
        if next_ugly == next3:
            i3 += 1
        if next_ugly == next5:
            i5 += 1
    return ugly[n - 1]

def zeckendorf_length(n):
    if n == 0:
        return 0
    fibs = [1, 2]
    while fibs[-1] <= n:
        fibs.append(fibs[-1] + fibs[-2])
    fibs.pop()
    count = 0
    remaining = n
    for f in reversed(fibs):
        if f <= remaining:
            remaining -= f
            count += 1
    return count

from math import factorial

def digit_sum_of_factorial(n):
    return sum(int(d) for d in str(factorial(n)))

def count_divisible_by_any(n, divisors):
    count = 0
    for x in range(1, n + 1):
        if any(x % d == 0 for d in divisors):
            count += 1
    return count
